// =========================================================
// V480 - Hastalık SSS: birbirinden bağımsız iki akordeon sütunu
// Soru kartları sırayla sol/sağ sütuna ayrılır. Mobilde görsel sıra korunur.
// =========================================================
function organizeDiseaseFaqV480(root) {
    if (!root) return;
    root.querySelectorAll('.ankilozan-faq-list-v85:not(.faq-independent-v480)').forEach((list) => {
        const items = Array.from(list.children).filter(el => el.classList.contains('ankilozan-faq-item-v85'));
        if (!items.length) return;

        const left = document.createElement('div');
        const right = document.createElement('div');
        left.className = 'faq-column-v480 faq-column-left-v480';
        right.className = 'faq-column-v480 faq-column-right-v480';

        items.forEach((item, index) => {
            const button = item.querySelector('.ankilozan-faq-question-v85');
            const answer = item.querySelector('.ankilozan-faq-answer-v85');
            const answerId = 'faq-answer-v480-' + (++organizeDiseaseFaqV480.lastId);
            item.classList.remove('is-open');
            item.style.setProperty('--faq-order-v480', index);
            if (button) {
                button.setAttribute('aria-expanded', 'false');
                button.setAttribute('aria-controls', answerId);
            }
            if (answer) {
                answer.id = answerId;
                answer.hidden = true;
            }
            (index % 2 === 0 ? left : right).appendChild(item);
        });
        list.replaceChildren(left, right);
        list.classList.add('faq-independent-v480');
    });
}
organizeDiseaseFaqV480.lastId = 0;

const menuButton = document.getElementById("menuButton");
const navbar = document.getElementById("navbar");
const siteHeader = document.getElementById("siteHeader");


// TELEFON MENÜSÜ

menuButton.addEventListener("click", () => {

    const isOpen = menuButton.classList.toggle("open");
    navbar.classList.toggle("open");

    menuButton.setAttribute("aria-expanded", isOpen ? "true" : "false");
});


// MENÜDEN BİR YERE BASINCA MENÜYÜ KAPAT

const menuLinks = document.querySelectorAll("#navbar a");

menuLinks.forEach(link => {

    link.addEventListener("click", () => {

        menuButton.classList.remove("open");
        navbar.classList.remove("open");
        menuButton.setAttribute("aria-expanded", "false");

    });

});


// AŞAĞI KAYDIRINCA HEADER EFEKTİ

window.addEventListener("scroll", () => {

    if (window.scrollY > 20) {
        siteHeader.classList.add("scrolled");
    } else {
        siteHeader.classList.remove("scrolled");
    }

});


// SAYFA AÇILMA ANİMASYONU

const revealElements = document.querySelectorAll(".reveal");

const observer = new IntersectionObserver(entries => {

    entries.forEach(entry => {

        if (entry.isIntersecting) {
            entry.target.classList.add("active");
        }

    });

}, {
    threshold: 0.12
});

revealElements.forEach(element => {
    observer.observe(element);
});


// FOOTER YILI

document.getElementById("year").textContent =
    new Date().getFullYear();




// RANDEVU TARİHİ: GEÇMİŞ TARİH SEÇİLEMEZ
const appointmentDate = document.getElementById("date");

if (appointmentDate) {
    const today = new Date();
    const year = today.getFullYear();
    const month = String(today.getMonth() + 1).padStart(2, "0");
    const day = String(today.getDate()).padStart(2, "0");

    appointmentDate.min = `${year}-${month}-${day}`;
}

// ================================
// RANDEVU WHATSAPP FORMU
// ================================

const appointmentForm = document.getElementById("appointmentForm");

// TEST WHATSAPP NUMARASI
const whatsappNumber = "905349309880";

const appointmentModal =
    document.getElementById("appointmentModal");

const appointmentPreview =
    document.getElementById("appointmentPreview");

const appointmentModalClose =
    document.getElementById("appointmentModalClose");

const appointmentModalBackdrop =
    document.getElementById("appointmentModalBackdrop");

const appointmentEditButton =
    document.getElementById("appointmentEditButton");

const appointmentConfirmButton =
    document.getElementById("appointmentConfirmButton");

let pendingWhatsappURL = "";


function closeAppointmentModal() {

    appointmentModal.classList.remove("show");

    appointmentModal.setAttribute(
        "aria-hidden",
        "true"
    );

    document.body.classList.remove("modal-open");

}


if (appointmentForm) {

    appointmentForm.addEventListener("submit", function(event) {

        event.preventDefault();

        const name = document.getElementById("name")?.value.trim() || "";
        const age = document.getElementById("age")?.value.trim() || "";
        const complaint = document.getElementById("complaint")?.value.trim() || "";
        const phone = document.getElementById("phone")?.value.trim() || "";

        const cleanPhone = phone.replace(/\D/g, "");

        if (!name || !age || !complaint || cleanPhone.length < 10) {
            alert("Lütfen isim soyad, yaş, şikayet / ağrı bilgisi ve telefon numaranızı eksiksiz doldurun.");
            return;
        }

        const message =
`Merhaba,

*RANDEVU TALEBİ*
------------------------------

*Ad Soyad:* ${name}
*Yaş:* ${age}
*Telefon:* ${phone}
*Şikayet / Hastalık / Ağrı:* ${complaint}

------------------------------

Uygunluk durumuna göre dönüş sağlayabilir misiniz?

Teşekkür ederim.`;

        pendingWhatsappURL =
            "https://wa.me/" +
            whatsappNumber +
            "?text=" +
            encodeURIComponent(message);

        if (appointmentPreview) {
            // V534: Hasta tarafından girilen metin HTML olarak çalıştırılmaz.
            // Mevcut önizleme satırlarının sınıfları / görünümü korunur.
            const rowsV534 = [
                ["Ad Soyad", name],
                ["Yaş", age],
                ["Telefon", phone],
                ["Şikayet / Hastalık / Ağrı", complaint]
            ];
            appointmentPreview.replaceChildren(...rowsV534.map(([label, value]) => {
                const row = document.createElement("div");
                row.className = "preview-row";
                const title = document.createElement("span");
                title.textContent = label;
                const content = document.createElement("strong");
                content.textContent = value;
                row.append(title, content);
                return row;
            }));
        }

        if (appointmentModal) {
            appointmentModal.classList.add("show");
            appointmentModal.setAttribute("aria-hidden", "false");
            document.body.classList.add("modal-open");
        } else {
            window.open(pendingWhatsappURL, "_blank", "noopener,noreferrer");
        }

    });

}


