// =========================================================
// V508 - ÖNE ÇIKAN MAKALELER: arama ve konu filtreleri.
// Yalnızca kart görünürlüğünü değiştirir; site gezinmesini etkilemez.
// =========================================================
(function(){
    const grid=document.getElementById('featuredArticlesGridV508');
    const search=document.getElementById('featuredArticleSearchV508');
    const output=document.getElementById('featuredArticleResultsV508');
    const empty=document.getElementById('featuredArticlesEmptyV508');
    if(!grid || !search || !output || !empty) return;
    const cards=Array.from(grid.querySelectorAll('[data-featured-article-card-v508]'));
    const buttons=Array.from(document.querySelectorAll('[data-featured-article-category-v508]'));
    let category='Tümü';
    const normalize=str=>String(str||'').toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
    function filter(){
        const query=normalize(search.value);
        let visible=0;
        cards.forEach(card=>{
            const matchesCategory=category==='Tümü' || card.dataset.category===category;
            const matchesText=!query || normalize(card.dataset.search).includes(query);
            const show=matchesCategory && matchesText;
            card.hidden=!show;
            if(show) visible++;
        });
        output.textContent=visible+' makale listeleniyor';
        empty.hidden=visible!==0;
    }
    buttons.forEach(button=>button.addEventListener('click',()=>{
        category=button.dataset.featuredArticleCategoryV508||'Tümü';
        buttons.forEach(item=>{
            const active=item===button;
            item.classList.toggle('is-active',active);
            item.setAttribute('aria-pressed',String(active));
        });
        filter();
    }));
    search.addEventListener('input',filter);
    filter();
})();


// =========================================================
// V510 - MAKALE KARTLARININ SİTE İÇİ OKUMA ALANINI AÇMASI
// Arama/filtre aynı kalır; dış siteye yönlendirme yapılmaz.
// =========================================================
(function(){
    const page=document.getElementById('generalFeaturedPageV124');
    const grid=document.getElementById('featuredArticlesGridV508');
    const toolbar=page && page.querySelector('.featured-articles-toolbar-v508');
    const reader=document.getElementById('featuredArticleReaderV510');
    const content=document.getElementById('featuredArticleReaderContentV510');
    const back=document.getElementById('featuredArticleBackV510');
    const empty=document.getElementById('featuredArticlesEmptyV508');
    if(!page || !grid || !toolbar || !reader || !content || !back || !empty) return;

    let openKey=null;
    let lastTrigger=null;
    let scrollBefore=0;
    const jumpTo=(node)=>{
        const menu=document.getElementById('globalConnectedNavV402');
        const rect=menu ? menu.getBoundingClientRect() : null;
        const offset=rect && rect.height>0 && rect.height<220 ? rect.height+20 : 145;
        window.scrollTo({top:Math.max(0,window.scrollY+node.getBoundingClientRect().top-offset),behavior:'auto'});
    };
    function openArticle(key,trigger){
        const tpl=page.querySelector('[data-featured-article-template-v510="'+key+'"]');
        if(!tpl) return;
        if(openKey===null) scrollBefore=window.scrollY;
        lastTrigger=trigger;
        openKey=key;
        content.replaceChildren(tpl.content.cloneNode(true));
        toolbar.hidden=true;
        grid.hidden=true;
        empty.hidden=true;
        reader.hidden=false;
        requestAnimationFrame(()=>{jumpTo(reader);back.focus({preventScroll:true});});
    }
    function closeArticle(restoreScroll=true){
        if(openKey===null) return;
        openKey=null;
        reader.hidden=true;
        content.replaceChildren();
        toolbar.hidden=false;
        grid.hidden=false;
        const search=document.getElementById('featuredArticleSearchV508');
        if(search) search.dispatchEvent(new Event('input',{bubbles:true}));
        if(restoreScroll){requestAnimationFrame(()=>{
            window.scrollTo({top:scrollBefore,behavior:'auto'});
            if(lastTrigger && lastTrigger.isConnected) lastTrigger.focus({preventScroll:true});
        });}
    }
    // V511: Makale görüntüleyicisini geçmiş gezinmesiyle senkron tut.
    window.siteArticleReaderV511 = {
        open: (key) => {
            const button=page.querySelector('[data-featured-article-open-v510="'+key+'"]');
            if (button) openArticle(key,button);
        },
        close: () => closeArticle(false),
        current: () => openKey
    };
    page.querySelectorAll('[data-featured-article-open-v510]').forEach(btn=>{
        btn.addEventListener('click',()=>openArticle(btn.dataset.featuredArticleOpenV510,btn));
    });
    back.addEventListener('click',()=>closeArticle());
    page.querySelectorAll('[data-featured-article-back-v510]').forEach(btn=>btn.addEventListener('click',()=>closeArticle()));
    document.addEventListener('keydown',event=>{
        if(event.key==='Escape' && openKey!==null){event.preventDefault();closeArticle();}
    });
    document.addEventListener('click',event=>{
        if(openKey!==null && !page.contains(event.target)) closeArticle(false);
    },true);
})();


// =========================================================
// V511 - SİTENİN TAMAMINDA TEK BİR GERİ / İLERİ GEÇMİŞİ
// Eski V419 history işleyişini bozmadan, gerçek ekran durumunu saklar.
// Tarayıcı geri/ileri, ESC, sayfa üzerindeki geri tuşları ve yüzen
// geri tuşu aynı geçmişi kullanır. Makale okuyucu dahil.
// =========================================================
(function () {
    if (window.siteBackV511) return;

    // Sabit DOM öğeleri için küçük bir durum fotoğrafı; gerçek makale
    // metinlerini ya da kişisel form içeriklerini tarayıcı geçmişine yazmayız.
    const selector = [
        'section[aria-hidden]', 'article[aria-hidden]', '[hidden]',
        '[data-treatment-detail-view]', '[data-health-detail-view]',
        '[data-traditional-detail]', '[data-nutrition-detail]',
        '[data-info-guide-view]', '[data-info-guide-panel]',
        '[data-osteo-panel]', '[data-osteo-special-panel]',
        '[data-disease-detail-view]', '[data-pain-detail-view]',
        '[data-treatment-special-panel]', '[data-device-detail-panel]',
        '[data-ank-panel-v196]', '[data-ra-panel-v198]',
        '[data-about-panel-v116]', '[data-media-panel]',
        '[data-traditional-panel]', '[data-pain-full-panel-v215]',
        '[data-legal-doc-page]', '[data-manual-view-v364]',
        '[data-focus-panel]',
        '[data-featured-article-card-v508]',
        '[data-injection-detail-key-v362]', '[data-exercise-detail-v669]',
        '[role="tab"]', '[aria-current="page"]',
        '#traditionalOverviewV168', '#nutritionOverviewV175',
        '#featuredArticlesGridV508', '#featuredArticleReaderV510',
        '.featured-articles-toolbar-v508', '#featuredArticlesEmptyV508'
    ].join(',');
    const nodes = Array.from(document.querySelectorAll(selector));
    const rootPages = Array.from(document.querySelectorAll([
        '#tedaviAlanlariPage','#agriPage','#hakkimdaPage','#medyaPage',
        '#treatmentDetailPageV71','#generalHealthDetailPageV75',
        '#generalFeaturedPageV124','#infoGuidePageV143',
        '#deviceDetailPageV157','#siteFeedbackPageV332',
        '#traditionalOverviewV168','#nutritionOverviewV175',
        '#featuredArticleReaderV510',
        '[data-treatment-detail-view]','[data-health-detail-view]',
        '[data-traditional-detail]','[data-nutrition-detail]',
        '[data-info-guide-view]', '[data-about-panel-v116]',
        '[data-media-panel]', '[data-ank-panel-v196]', '[data-ra-panel-v198]',
        '[data-traditional-panel]', '[data-pain-full-panel-v215]',
        '[data-legal-doc-page]', '[data-manual-view-v364]',
        '[data-device-detail-panel]', '[data-osteo-panel]'
    ].join(',')));

    const rawPush = history.pushState.bind(history);
    const rawReplace = history.replaceState.bind(history);
    const stateKey = 'siteViewV511';
    const homeUrl = location.pathname + location.search;
    let restoring = false;
    let ticket = 0;
    let gesture = null;

    const cleanState = (state) => (state && typeof state === 'object' ? Object.assign({}, state) : {});
    const isSameOriginUrl = (url) => {
        try { return new URL(url || location.href, location.href).origin === location.origin; }
        catch (_) { return false; }
    };
    const snapshot = () => ({
        body: document.body.className,
        x: Math.round(window.scrollX || 0),
        y: Math.round(window.scrollY || 0),
        states: nodes.map((node) => [
            node.className && typeof node.className === 'string' ? node.className : '',
            node.getAttribute('aria-hidden'), node.hidden ? 1 : 0,
            node.getAttribute('aria-current'), node.getAttribute('aria-selected'),
            node.hasAttribute('open') ? 1 : 0
        ]),
        article: window.siteArticleReaderV511?.current?.() || null,
        injection: window.siteInjectionHistoryV679?.current?.() || null,
        osteoTab: window.siteOsteoHistoryV679?.current?.() || null,
        osteoManual: window.siteOsteoManualHistoryV679?.current?.() || null,
        exercise: window.siteExerciseHistoryV679?.current?.() || null
    });
    const saveCurrent = () => {
        if (restoring) return;
        try {
            const state = cleanState(history.state);
            state[stateKey] = snapshot();
            rawReplace(state, '', location.href);
        } catch (e) {
            // Geçmiş boyutu sınırına ulaşılırsa site gezinmesi yine çalışsın.
            console.warn('V511: geçmiş ekranı kaydedilemedi', e);
        }
    };
    const fingerprint = () => {
        const body = Array.from(document.body.classList).filter(c =>
            /(open|active|page|detail|special)/.test(c) && !/(scrolled|fixed|animat)/.test(c)
        ).sort().join('.');
        const pages = rootPages.map(n =>
            (n.classList.contains('active') ? '1' : '0') +
            (n.getAttribute('aria-hidden') === 'false' ? '1' : '0') +
            (n.hidden ? '1' : '0')
        ).join('');
        // V679: Osteopati panelleri / PRP gibi hash'siz alt detaylar ayrı geçmiş halkasıdır.
        // Akordeon, kaydırma ve menü aç/kapat hareketleri sayfa geçişi değildir.
        const inPage = [
            ...document.querySelectorAll('[data-osteo-tab][aria-selected="true"]'),
            ...document.querySelectorAll('[data-osteo-panel]:not([hidden])'),
            ...document.querySelectorAll('[data-manual-view-v364]:not([hidden])'),
            ...document.querySelectorAll('[data-health-detail-view].active'),
            ...document.querySelectorAll('[data-treatment-detail-view].active'),
            ...document.querySelectorAll('[data-exercise-detail-v669]:not([hidden])')
        ].map(node => node.dataset.osteoTab || node.dataset.osteoPanel ||
            node.dataset.manualViewV364 || node.dataset.healthDetailView ||
            node.dataset.treatmentDetailView || node.dataset.exerciseDetailV669 || node.id).join(';');
        return body + '|' + pages + '|' + inPage + '|' +
            (window.siteArticleReaderV511?.current?.() || '') + '|' +
            (window.siteInjectionHistoryV679?.current?.() || '');
    };
    const hasSubpage = () => Boolean(location.hash && location.hash !== '#anasayfa') ||
        Array.from(document.body.classList).some(c => /(page|detail|special|featured|standalone)-open/.test(c)) ||
        Boolean(window.siteArticleReaderV511?.current?.());
    const atSiteDepth = () => Number(history.state && history.state.siteDepthV419) || 0;
    const shouldConvertReplace = (target) => Boolean(target && target.closest([
        '[data-traditional-open]','[data-nutrition-open]',
        '[data-info-guide-switch]','[data-traditional-back]',
        '[data-nutrition-back]'
    ].join(',')));

    // V419 tarafından kurulmuş pushState/replaceState sarmalayıcılarını
    // kullanarak siteDepthV419 değerini koruyoruz.
    history.pushState = function (state, title, url) {
        const result = rawPush(state, title, url);
        if (!restoring) {
            if (gesture) gesture.written = true;
            const turn = ++ticket;
            setTimeout(() => { if (turn === ticket) saveCurrent(); }, 70);
        }
        return result;
    };
    history.replaceState = function (state, title, url) {
        const targetUrl = url == null ? location.href : url;
        const changesUrl = isSameOriginUrl(targetUrl) &&
            new URL(targetUrl, location.href).href !== location.href;
        // Bazı alt sayfalar replaceState kullandığı için tarayıcı geri
        // okuna bir giriş bırakmıyordu. Kullanıcının bir sekmeye tıklaması
        // sonucu gerçekleşen bu geçişleri yalnızca o durumda push'a çevir.
        if (!restoring && gesture && gesture.convertReplace && changesUrl) {
            const result = history.pushState(state, title, targetUrl);
            gesture.written = true;
            return result;
        }
        const result = rawReplace(state, title, url);
        if (!restoring && changesUrl) {
            const turn = ++ticket;
            setTimeout(() => { if (turn === ticket) saveCurrent(); }, 70);
        }
        return result;
    };

    function restore(snapshotData) {
        if (!snapshotData || !Array.isArray(snapshotData.states)) return;
        restoring = true;
        try {
            const reader = window.siteArticleReaderV511;
            if (reader) {
                if (snapshotData.article && reader.current() !== snapshotData.article) reader.open(snapshotData.article);
                else if (!snapshotData.article && reader.current()) reader.close();
            }
            document.body.className = snapshotData.body || '';
            // V679: Geçmişteki en ilk kayıt ana sayfadır; alt sayfa
            // katmanının görsel modu geride kalmışsa ana ekranı tekrar aç.
            if (atSiteDepth() === 0 && !location.hash &&
                !/(?:page|detail|special|featured|standalone)-open/.test(document.body.className)) {
                document.body.classList.remove('global-subpage-open-v405');
                document.body.classList.add('global-home-open-v408');
            }
            snapshotData.states.forEach((values, i) => {
                const node = nodes[i];
                if (!node || !node.isConnected) return;
                if (typeof values[0] === 'string') node.setAttribute('class', values[0]);
                if (values[1] === null) node.removeAttribute('aria-hidden');
                else node.setAttribute('aria-hidden', values[1]);
                node.hidden = values[2] === 1;
                if (values[3] == null) node.removeAttribute('aria-current');
                else node.setAttribute('aria-current', values[3]);
                if (values[4] == null) node.removeAttribute('aria-selected');
                else node.setAttribute('aria-selected', values[4]);
                if (values[5]) node.setAttribute('open', '');
                else node.removeAttribute('open');
            });
            // Görünüm sınıfları eski hâline dönünce dinamik alt sayfa
            // başlıkları ve içerikleri de ilgili önceki seçime geri alınır.
            window.siteInjectionHistoryV679?.restore?.(snapshotData.injection || null);
            window.siteOsteoManualHistoryV679?.restore?.(snapshotData.osteoManual || null);
            window.siteExerciseHistoryV679?.restore?.(snapshotData.exercise || null);
            if (snapshotData.osteoTab && snapshotData.body?.includes('osteo-standalone-open-v260')) {
                window.siteOsteoHistoryV679?.restore?.(snapshotData.osteoTab);
            }
            window.scrollTo({ left: snapshotData.x || 0, top: snapshotData.y || 0, behavior: 'instant' });
        } finally {
            restoring = false;
            updateBackVisibility();
        }
    }

    function goBack() {
        // V556: Serum ayrıntısı, tarayıcı geçmişinden bağımsız bir alt görünüm.
        // Global geri okuna basılınca önce Damar Yolu serum kartlarına dön.
        const focusedSerumV556 = document.querySelector('[data-treatment-detail-view="damar-yolu"].serum-focus-v334');
        if (focusedSerumV556) {
            const closeIdsV556 = {
                ozone: 'closeOzoneDetailV239', 'vitamin-c': 'closeVitaminCDetailV235',
                karnitin: 'closeKarnitinDetailV243', selenium: 'closeSeleniumDetailV244',
                nad: 'closeNadDetailV242', glutathione: 'closeGlutathioneDetailV241',
                'major-ozone': 'closeMajorOzoneDetailV240'
            };
            const closeId = closeIdsV556[focusedSerumV556.dataset.activeSerumV334];
            if (closeId && document.getElementById(closeId)) {
                document.getElementById(closeId).click();
                updateBackVisibility();
                return;
            }
        }
        if (atSiteDepth() > 0) {
            history.back();
        } else if (window.siteArticleReaderV511?.current?.()) {
            window.siteArticleReaderV511.close();
            updateBackVisibility();
        } else if (hasSubpage()) {
            // Sayfa URL'si doğrudan alt bölüme yapıştırılarak açılmışsa.
            const brand = document.getElementById('globalConnectedBrandV402');
            if (brand) brand.click();
            else location.href = homeUrl;
        }
    }

    // Tüm site için küçük ve daima erişilebilir bir geri tuşu.
    const backButton = document.createElement('button');
    backButton.type = 'button';
    backButton.id = 'siteGlobalBackV511';
    backButton.className = 'site-global-back-v511';
    backButton.setAttribute('aria-label', 'Önceki sayfaya dön');
    backButton.title = 'Önceki ziyaret edilen bölüme dön';
    backButton.innerHTML = '<span aria-hidden="true">‹</span>';
    backButton.hidden = true;
    document.body.appendChild(backButton);
    backButton.addEventListener('click', goBack);

    function updateBackVisibility() {
        backButton.hidden = !(hasSubpage() || atSiteDepth() > 0);
    }

    // Eski tekil geri butonları artık aynı geçmişe yönlendirilsin.
    // Slider sol okları ve sayfa başına dönme tuşu BU LİSTEDE YOK.
    const backSelectors = [
        '[data-traditional-back]', '[data-nutrition-back]',
        '#featuredArticleBackV510', '[data-featured-article-back-v510]',
        '#painFullBackV215', '#osteoSpecialBackV259',
        // V631: Bitkilere Dön kendi Fitoterapi yönlendirmesini yönetir;
        // geçmişi geri alan V511 bu butona müdahale etmemeli.
        '#deviceDetailBackV157', '#deviceDetailBreadcrumbBackV157',
        '#injectionSpecialBackV362', '#osteoManualDetailBackV364',
        '[data-exercise-detail-back-v669]', '[data-exercise-back-v669]',
        // V556: Serum detay geri butonları global history.back'e bağlanmaz.
        // Kendi V235–V334 close handler'ları normal şekilde çalışır.
    ].join(',');

    // Navigasyonun başında AYRILACAĞIMIZ sayfayı kaydet (click bubbling
    // dinleyicilerinden önce). Böylece browser back gerçek önceki ekranı açar.
    document.addEventListener('click', (event) => {
        const target = event.target instanceof Element ? event.target : null;
        if (!target || restoring) return;
        // V679: Menü içindeki programatik ikinci tıklama aynı gezinme değil;
        // ayrıldığımız ana sayfanın geçmiş kaydını yanlışlıkla ezmesin.
        if (window.__v548BridgeClick === true || window.__v533ImmediateNav === true) return;
        const back = target.closest(backSelectors);
        if (back && atSiteDepth() > 0) {
            event.preventDefault();
            event.stopImmediatePropagation();
            goBack();
            return;
        }
        const control = target.closest('a,button,summary,[role="tab"],.injection-card-v72[data-injection-detail-key-v362]');
        if (!control || control === backButton) return;
        const isNavigation = !control.closest('form') && !control.matches(
            '[data-traditional-card-toggle],.traditional-card-details-v501 summary'
        );
        if (!isNavigation) return;
        const before = fingerprint();
        saveCurrent();
        const clickGesture = {
            target: control, convertReplace: shouldConvertReplace(control),
            written: false, before, url: location.href
        };
        gesture = clickGesture;
        // Önce eski handler'ların tamamlanmasını bekle; hash değişmeden açılan
        // detay/sekme ekranlarına da ayrı geri geçmişi oluştur.
        setTimeout(() => {
            if (gesture === clickGesture) gesture = null;
            if (restoring) return;
            if (location.href === clickGesture.url && fingerprint() !== before &&
                history.state && history.state[stateKey] && !clickGesture.written) {
                history.pushState(cleanState(history.state), '', location.href);
            }
            updateBackVisibility();
        }, 220);
    }, true);

    window.addEventListener('popstate', (event) => {
        const target = event.state && event.state[stateKey];
        const expectedUrl = location.href;
        ++ticket;
        // Mevcut sayfanın 25+ eski popstate işleyicisi önce tamamlanmalı.
        setTimeout(() => {
            if (expectedUrl !== location.href) return;
            if (target) restore(target);
            else updateBackVisibility();
        }, 140);
    });
    window.addEventListener('hashchange', () => setTimeout(updateBackVisibility, 70));
    window.addEventListener('pageshow', updateBackVisibility);

    window.siteBackV511 = { goBack, refresh: updateBackVisibility };
    saveCurrent();
    updateBackVisibility();
})();


// =========================================================
// V512 - GELENEKSEL TEDAVİ: ALT SAYFADAN DİREKT ÜÇ KARTA DÖNÜŞ
// Akupunktur/Sülük/Hacamat alt sayfaları eski tanıtım/hero ekranına
// dönmez. Geri düğmesi ana Geleneksel Tedavi seçim ekranına gider.
// =========================================================
(function () {
    const treatmentView = document.querySelector('[data-treatment-detail-view="geleneksel-tedavi"]');
    const overview = document.getElementById('traditionalOverviewV168');
    if (!treatmentView || !overview) return;

    const details = Array.from(treatmentView.querySelectorAll('[data-traditional-detail]'));

    function openTraditionalOverviewV512(updateAddress = true) {
        // Eski uygulama hero'suna dönmek yerine, üç kartlı seçim ekranını göster.
        details.forEach(detail => {
            detail.classList.remove('active', 'is-traditional-subpage-open-v331');
            detail.setAttribute('aria-hidden', 'true');
            detail.querySelector('.traditional-detail-hero-v330')?.setAttribute('aria-hidden', 'true');
            detail.querySelector('.traditional-tabs-stage-v330')?.setAttribute('aria-hidden', 'true');
            detail.querySelectorAll('[data-traditional-panel]').forEach(panel => {
                panel.classList.remove('is-active');
                panel.setAttribute('aria-hidden', 'true');
            });
            detail.querySelectorAll('[data-traditional-tab]').forEach(button => {
                button.classList.remove('is-active');
                button.setAttribute('aria-selected', 'false');
            });
        });
        overview.classList.add('active');
        overview.setAttribute('aria-hidden', 'false');

        if (updateAddress && window.history.replaceState) {
            // Yeni bir ara ekran/geçmiş halkası üretme.
            window.history.replaceState(window.history.state, '', '#geleneksel-tedavi');
        }

        // Üstteki sabit site menüsü kartların üstüne gelmesin.
        const nav = document.querySelector('.treatment-detail-nav-modern-v160');
        const navBottom = nav ? Math.max(0, nav.getBoundingClientRect().bottom) : 0;
        const offset = Math.max(18, navBottom + 14);
        const destination = window.scrollY + overview.getBoundingClientRect().top - offset;
        window.scrollTo({ top: Math.max(0, destination), behavior: 'smooth' });
        window.siteBackV511?.refresh?.();
    }

    // Capture aşaması: V331'in eski alt-sayfa geri işleyicisinden ve
    // V511'in tüm-site geçmiş işleyicisinden önce bu özel dönüşü uygula.
    window.addEventListener('click', (event) => {
        const target = event.target;
        if (!(target instanceof Element)) return;
        const back = target.closest('[data-traditional-sub-back], [data-traditional-back]');
        if (!back || !treatmentView.contains(back)) return;
        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();
        openTraditionalOverviewV512(true);
    }, true);

    // Tarayıcı geri/ileri ile daha önce kaydedilmiş "eski hero" durumuna
    // dönülürse de kullanıcının istemediği tanıtım ekranını atla.
    window.addEventListener('popstate', () => {
        window.setTimeout(() => {
            const parent = document.getElementById('treatmentDetailPageV71');
            if (!document.body.classList.contains('treatment-detail-open-v71') ||
                (parent && parent.getAttribute('aria-hidden') === 'true')) return;
            const legacyHeroOpen = details.some(detail =>
                detail.classList.contains('active') &&
                !detail.classList.contains('is-traditional-subpage-open-v331')
            );
            if (legacyHeroOpen && !overview.classList.contains('active')) {
                openTraditionalOverviewV512(false);
            }
        }, 220); // V511, popstate'de 140 ms sonra geçmişi geri yükler.
    });
})();


/* ============================================================
   V517 - Ağrı sayfasında sabit üst menünün gerçek yüksekliğini
   ölçerek sol rehberin üst menü ile çakışmasını önler.
   ============================================================ */
(function(){
    const menu = document.getElementById('globalConnectedNavV402');
    if (!menu) return;
    const updatePainStickyOffsetV517 = () => {
        const marginTop = window.innerWidth <= 560 ? 5 : 8;
        const menuHeight = menu.getBoundingClientRect().height || 104;
        document.documentElement.style.setProperty('--pain-sidebar-top-v517',
            Math.ceil(menuHeight + marginTop + 14) + 'px');
    };
    updatePainStickyOffsetV517();
    window.addEventListener('resize', updatePainStickyOffsetV517, {passive:true});
    if (typeof ResizeObserver !== 'undefined') {
        new ResizeObserver(updatePainStickyOffsetV517).observe(menu);
    }
})();


// =============================================================
// V518 — Ağrı üst menüsü fixed iken sayfa boşluğunu ve detay
// ekranının açılacağı güvenli yüksekliği menü boyuna göre ayarla.
// =============================================================
(function () {
    const nav = document.getElementById('globalConnectedNavV402');
    if (!nav) return;
    // V519: Ağrı listesinde fixed menü kalktı; boşluk elemanı eklenmez.
    document.getElementById('painNavSpacerV518')?.remove();
    const root = document.documentElement;
    let frame = 0;
    function syncPainNavV518() {
        frame = 0;
        const active = document.body.classList.contains('pain-page-open') ||
            document.body.classList.contains('pain-full-detail-open-v215');
        if (!active) return;
        // Menünün gerçek yüksekliğini ölç: masaüstü ve mobilde doğru boşluk.
        const top = window.innerWidth <= 560 ? 5 : 8;
        const height = Math.ceil(nav.getBoundingClientRect().height || 104);
        const safe = top + height + 12;
        root.style.setProperty('--pain-nav-reserve-v518', safe + 'px');
        root.style.setProperty('--pain-sidebar-top-v517', safe + 'px');
    }
    function schedule() {
        if (frame) return;
        frame = window.requestAnimationFrame(syncPainNavV518);
    }
    new MutationObserver(schedule).observe(document.body, {
        attributes: true, attributeFilter: ['class']
    });
    if (typeof ResizeObserver !== 'undefined') new ResizeObserver(schedule).observe(nav);
    window.addEventListener('resize', schedule, {passive:true});
    window.addEventListener('pageshow', schedule);
    schedule();
})();


// V522 — Osteopati bağımsız detayında ortak üst menünün ekranı izlemesini önle.
// Mevcut V308 yalnız eski/kapalı tedavi navını izliyordu; ekranda görünen
// ortak V402 menüsünü, aynı detay panelinin kaydırmasıyla eşleştir.
(function () {
    const detail = document.getElementById('osteoSpecialViewV259');
    const nav = document.getElementById('globalConnectedNavV402');
    if (!detail || !nav) return;
    let scheduled = false;
    function applyV522() {
        scheduled = false;
        const active = document.body.classList.contains('osteo-standalone-open-v260') &&
                       !detail.hidden;
        if (!active) {
            nav.style.removeProperty('--osteo-main-nav-scroll-y-v522');
            return;
        }
        const distance = Math.max(0, Math.min(detail.scrollTop,
            nav.getBoundingClientRect().height + 30));
        nav.style.setProperty('--osteo-main-nav-scroll-y-v522', (-distance) + 'px');
    }
    function updateV522() {
        if (scheduled) return;
        scheduled = true;
        requestAnimationFrame(applyV522);
    }
    detail.addEventListener('scroll', updateV522, {passive:true});
    new MutationObserver(updateV522).observe(document.body, {
        attributes:true, attributeFilter:['class']
    });
    window.addEventListener('resize', updateV522, {passive:true});
    window.addEventListener('pageshow', updateV522);
    updateV522();
})();


// V528 • Estetiğe Bakış: dört karttan tam detay sayfasına geçiş, geri/ileri uyumu.
(function () {
    'use strict';
    const root = document.querySelector('.aesthetic-view-v526[data-treatment-detail-view="estetik"]');
    if (!root) return;
    const overview = root.querySelector('.aesthetic-overview-v528');
    const reading = root.querySelector('.aesthetic-reading-v528');
    const cards = Array.from(root.querySelectorAll('[data-aesthetic-topic-v527]'));
    const pages = Array.from(root.querySelectorAll('[data-aesthetic-read-v528]'));
    const keys = pages.map(page => page.dataset.aestheticReadV528);
    if (!overview || !reading || !cards.length || !pages.length) return;
    let lastCard = null;

    function moveToStart() {
        const treatmentLayer = document.getElementById('treatmentDetailPageV71');
        if (treatmentLayer && treatmentLayer.scrollHeight > treatmentLayer.clientHeight + 40 &&
            getComputedStyle(treatmentLayer).overflowY !== 'visible') {
            treatmentLayer.scrollTop = 0;
        }
        window.scrollTo({ top: 0, left: 0, behavior: 'instant' });
    }

    function renderTopic(key, options = {}) {
        const isDetail = keys.includes(key);
        overview.hidden = isDetail;
        reading.hidden = !isDetail;
        root.classList.toggle('aesthetic-is-reading-v528', isDetail);
        pages.forEach(page => { page.hidden = !isDetail || page.dataset.aestheticReadV528 !== key; });
        root.querySelectorAll('.ae604-read-nav [data-aesthetic-next-v528]').forEach(button => {
            if (button.dataset.aestheticNextV528 === key) {
                button.setAttribute('aria-current', 'page');
            } else button.removeAttribute('aria-current');
        });
        if (options.scroll !== false) moveToStart();
        if (options.focus) {
            if (isDetail) {
                const heading = pages.find(page => page.dataset.aestheticReadV528 === key)?.querySelector('h2');
                if (heading) { heading.setAttribute('tabindex', '-1'); heading.focus({ preventScroll: true }); }
            } else if (lastCard) lastCard.focus({ preventScroll: true });
        }
    }

    function openTopic(key, source, updateHistory = true) {
        if (!keys.includes(key)) return;
        if (source) lastCard = source;
        if (updateHistory) {
            // Same #estetik route. Moving between readings replaces that one detail
            // entry, so the in-page back button always returns to the overview.
            const state = { ...(history.state || {}), aestheticTopicV528: key };
            if (root.classList.contains('aesthetic-is-reading-v528')) {
                history.replaceState(state, '', location.href);
            } else {
                history.pushState(state, '', location.href);
            }
        }
        renderTopic(key, { focus: true });
    }

    function goBack() {
        if (history.state && keys.includes(history.state.aestheticTopicV528) &&
            location.hash === '#estetik') {
            history.back();
        } else renderTopic(null, { focus: true });
    }

    cards.forEach(card => {
        card.addEventListener('click', () => openTopic(card.dataset.aestheticTopicV527, card));
    });
    root.querySelectorAll('[data-aesthetic-next-v528]').forEach(button => {
        button.addEventListener('click', () => openTopic(button.dataset.aestheticNextV528));
    });
    root.querySelectorAll('[data-aesthetic-back-v528]').forEach(button => {
        button.addEventListener('click', goBack);
    });

    window.addEventListener('popstate', event => {
        if (location.hash !== '#estetik') {
            renderTopic(null, { scroll: false });
            return;
        }
        const key = event.state && event.state.aestheticTopicV528;
        renderTopic(key, { focus: false });
    });
    // Returning via a normal site menu should open the four-card overview.
    document.addEventListener('click', event => {
        const opener = event.target.closest('[data-treatment-detail="estetik"], [data-treatment-top="estetik"]');
        if (opener && !root.contains(opener)) renderTopic(null, { scroll: false });
    }, true);
    const initial = location.hash === '#estetik' && history.state && history.state.aestheticTopicV528;
    renderTopic(initial, { scroll: false });
})();;


// ======================================================================
// V535 — Premium site animasyonları: mevcut yönlendirme/sekme mantığına dokunmaz.
// Hero fotoğrafına hafif parallax ve sadece görünür kartlara giriş hareketi.
// ======================================================================
(function initVisualMotionV535() {
    'use strict';
    const hero = document.querySelector('.hero-home-v85');
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
    const finePointer = window.matchMedia('(hover: hover) and (pointer: fine)');
    let pointerFrame = 0;
    let lastPointer = null;
    function applyPointer() {
        pointerFrame = 0;
        if (!hero || !lastPointer || reduceMotion.matches || !finePointer.matches ||
            !document.body.classList.contains('global-home-open-v408')) return;
        const rect = hero.getBoundingClientRect();
        if (rect.width <= 0 || rect.height <= 0) return;
        const x = Math.max(-1, Math.min(1, (lastPointer.x - rect.left) / rect.width * 2 - 1));
        const y = Math.max(-1, Math.min(1, (lastPointer.y - rect.top) / rect.height * 2 - 1));
        hero.style.setProperty('--v535-photo-x', (-x * 6).toFixed(2) + 'px');
        hero.style.setProperty('--v535-photo-y', (-y * 4).toFixed(2) + 'px');
    }
    if (hero) {
        hero.addEventListener('pointermove', function (event) {
            if (event.pointerType !== 'mouse' || reduceMotion.matches || !finePointer.matches) return;
            lastPointer = {x:event.clientX, y:event.clientY};
            if (!pointerFrame) pointerFrame = requestAnimationFrame(applyPointer);
        }, {passive:true});
        hero.addEventListener('pointerleave', function () {
            lastPointer = null;
            hero.style.setProperty('--v535-photo-x','0px');
            hero.style.setProperty('--v535-photo-y','0px');
        });
    }
    // Görünür kartlara bir kez animasyon: gizli sayfalarda veya modal içinde
    // yanlışlıkla kartları saklamaz. Liste sınırı büyük sayfaları korur.
    const selector = [
        '.treatment-card-v77','.pain-card-v76','.serum-card-v71',
        '.injection-card-v72','.featured-article-card-v508',
        '.traditional-intro-card-v167','.aesthetic-topic-card-v527'
    ].join(',');
    if (!('IntersectionObserver' in window)) return;
    const seen = new WeakSet();
    const observed = new WeakSet();
    const io = new IntersectionObserver(function (entries) {
        for (const entry of entries) {
            if (!entry.isIntersecting) continue;
            io.unobserve(entry.target);
            seen.add(entry.target);
            entry.target.style.setProperty('--v535-reveal-delay',
                ((Array.prototype.indexOf.call(entry.target.parentElement?.children || [],entry.target) % 4) * 65) + 'ms');
            entry.target.classList.add('v535-reveal-seen');
        }
    }, {threshold:0.12, rootMargin:'0px 0px -25px 0px'});
    let scanFrame = 0;
    function scanActiveCards() {
        scanFrame = 0;
        if (reduceMotion.matches) return;
        let count = 0;
        document.querySelectorAll(selector).forEach(function (el) {
            if (count >= 140 || observed.has(el) || seen.has(el)) return;
            // display:none sayfaları şimdi gözlemleme; açılınca tekrar taranır.
            if (!el.getClientRects().length) return;
            if (el.closest('[hidden], [aria-hidden="true"]')) return;
            observed.add(el);
            io.observe(el);
            count++;
        });
    }
    function scheduleScan() {
        if (!scanFrame) scanFrame = requestAnimationFrame(scanActiveCards);
    }
    const classChanges = new MutationObserver(scheduleScan);
    classChanges.observe(document.body,{attributes:true,attributeFilter:['class']});
    document.addEventListener('click',scheduleScan, {passive:true});
    window.addEventListener('pageshow',scheduleScan,{passive:true});
    reduceMotion.addEventListener?.('change',scheduleScan);
    scheduleScan();
})();


// =====================================================================
// V536 | Yeni global menü sinematik geçişleri
// V533'te kapatılmış eski global animasyonu GERİ AÇMAZ: ortak menüdeki
// gerçek tıklamayı örtü ekranının orta noktasında bir kez yürütür.
// Bölüm menüleri, geçmiş/ESC ve hızlı ardışık tıklamalar korunur.
// =====================================================================
(function initSectionSwitchV536() {
    'use strict';
    const nav = document.getElementById('globalConnectedNavV402');
    const overlay = document.getElementById('siteRouteTransitionV536');
    if (!nav || !overlay) return;
    const title = overlay.querySelector('#routeTitleV536');
    const kicker = overlay.querySelector('#routeEyebrowV536');
    const subtitle = overlay.querySelector('#routeSubtitleV536');
    const icon = overlay.querySelector('#routeIconV536');
    if (!title || !kicker || !subtitle || !icon) return;

    const selector = [
        '#globalConnectedBrandV402', '[data-v402-route]',
        '[data-v402-treatment]', '[data-v402-health]',
        '[data-v402-guide]', '[data-v402-feedback]', '[data-v402-legal]'
    ].join(',');
    const treatmentNames = {
        'osteopati':['Osteopati','Bütüncül manuel yaklaşım','✧','osteopati'],
        'fitoterapi':['Fitoterapi','Bitkisel destekler ve beslenme','❧','fitoterapi'],
        'damar-yolu':['Damar Yolu Uygulamaları','Uygulamaları keşfedin','✚','health'],
        'ozon-tedavisi':['Ozon Tedavisi','Uygulamalar hakkında bilgiler','◎','health'],
        'igne':['İğneli Uygulamalar','Uygulamaları keşfedin','✦','osteopati'],
        'cihaz-uygulamalari':['Cihaz Uygulamaları','Cihaz ve teknoloji uygulamaları','◈','areas'],
        'geleneksel-tedavi':['Geleneksel Tedaviler','Geleneksel uygulamalar','❋','fitoterapi'],
        'estetik':['Estetiğe Bakış','Bütüncül estetik yaklaşımlar','◇','info']
    };
    const routeNames = {
        home:['Ana Sayfa','Dr. Ceyhun Nuri','✚','general'],
        areas:['Tedavi Alanları','Bilgilendirme ve değerlendirme alanları','▦','areas'],
        pain:['Ağrı','Ağrı bölgelerini keşfedin','◎','pain'],
        media:['Sosyal Medya','Video ve yayınlar','▶','media']
    };
    const healthNames = {
        beslenme:['Beslenme','Beslenme rehberi','❧','fitoterapi'],
        supplementler:['Supplementler','Destek ürünleri','✦','health'],
        kurler:['Detoks Kürleri','Çin ve Doğu tıbbı bakışı','✧','fitoterapi'],
        egzersizler:['Egzersizler','Hareket ve yaşam','↗','osteopati']
    };
    let startTimer=null, endTimer=null, landingTimer=null;
    let bypass=false;
    let sequence=0;
    const prefersReducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');

    function getMeta(target) {
        if (target.id === 'globalConnectedBrandV402') return routeNames.home;
        if (target.dataset.v402Treatment) return treatmentNames[target.dataset.v402Treatment] || [target.textContent.trim(),'Tedavi uygulamaları','✦','general'];
        if (target.dataset.v402Route) return routeNames[target.dataset.v402Route] || [target.textContent.trim(),'Yeni bölüm','✦','general'];
        if (target.dataset.v402Health) return healthNames[target.dataset.v402Health] || [target.textContent.trim(),'Genel sağlık','✚','health'];
        return [target.textContent.trim(),'Bilgi ve rehberler','i','info'];
    }

    function clearTimers() {
        if (startTimer !== null) clearTimeout(startTimer);
        if (endTimer !== null) clearTimeout(endTimer);
        if (landingTimer !== null) clearTimeout(landingTimer);
        startTimer=endTimer=landingTimer=null;
    }
    function cancel() {
        sequence++;
        clearTimers();
        overlay.classList.remove('is-running-v536');
        overlay.setAttribute('aria-hidden','true');
        document.body.classList.remove('v536-content-land');
    }
    function runOriginal(target) {
        bypass=true;
        try { target.click(); }
        finally { bypass=false; }
    }
    // Escape ve tarayıcı geçmişi ile bekleyen sayfa değişimi asla sonra tetiklenmesin.
    document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape' && overlay.classList.contains('is-running-v536')) cancel();
    }, true);
    window.addEventListener('popstate',cancel);
    window.addEventListener('pagehide',cancel);

    document.addEventListener('click',function (event) {
        if (bypass || window.__v548BridgeClick || !(event.target instanceof Element)) return;
        if (event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
        const trigger=event.target.closest(selector);
        if (!trigger || !nav.contains(trigger) || trigger.disabled || trigger.getAttribute('aria-disabled')==='true') return;
        // Tıklama animasyon süresince tutulur, sonra normal V402 handler'ına
        // bırakılır. Açılır menüyü açan ana butonlar burada yakalanmaz.
        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();
        cancel();
        if (typeof window.cancelSiteTransitionV533 === 'function') window.cancelSiteTransitionV533();
        if (prefersReducedMotion.matches) { runOriginal(trigger); return; }
        const current=sequence;
        const meta=getMeta(trigger);
        title.textContent=meta[0];
        subtitle.textContent=meta[1];
        icon.textContent=meta[2];
        kicker.textContent='DR. CEYHUN NURİ  •  '+(meta[3]==='general'?'ANA SAYFA':'KEŞFET');
        overlay.dataset.v536Theme=meta[3];
        // Aynı isimli animasyonu sonraki tıklamada sıfırdan oynat.
        overlay.classList.remove('is-running-v536');
        void overlay.offsetWidth;
        overlay.setAttribute('aria-hidden','false');
        overlay.classList.add('is-running-v536');
        startTimer=window.setTimeout(function () {
            startTimer=null;
            if (current!==sequence) return;
            runOriginal(trigger);
            document.body.classList.add('v536-content-land');
            landingTimer=window.setTimeout(function () {
                landingTimer=null;
                if (current===sequence) document.body.classList.remove('v536-content-land');
            },650);
        },300);
        endTimer=window.setTimeout(function () {
            endTimer=null;
            if (current!==sequence) return;
            overlay.classList.remove('is-running-v536');
            overlay.setAttribute('aria-hidden','true');
        },835);
    },true);
})();

// V542: V536 özgün, kolajsız bölüm geçiş animasyonlarına geri dönüldü.

// V543: Ağrı tam detayından Tedavi Alanları geçişinin katman temizliği düzeltildi.


// V544 — Tedavi/Genel Sağlık/Bilgi açılır menüleri alt sekmelerde içerik
// katmanlarının altında kalmasın; menü kapanınca normal z-index'e dönsün.
(function syncGlobalDropdownLayerV544(){
    'use strict';
    const nav = document.getElementById('globalConnectedNavV402');
    if (!nav) return;
    const menus = Array.from(nav.querySelectorAll('.global-connected-menu-v402'));
    const sync = () => {
        nav.classList.toggle('v544-dropdown-front', menus.some(menu => menu.classList.contains('open')));
    };
    menus.forEach(menu => {
        new MutationObserver(sync).observe(menu, {attributes:true, attributeFilter:['class']});
    });
    sync();
})();


// V545 | Osteopati'de 7.-8. seçenekler örtülmesin: sayfanın en üstünde
// görsel menü kopyası göster, gerçek V402 düğmelerini aynen çalıştır.
(function ensureWholeTreatmentDropdownV545(){
    'use strict';
    if (document.getElementById('v548PremiumNav')) return;
    const nav = document.getElementById('globalConnectedNavV402');
    const menu = nav && nav.querySelector('[data-v402-menu="treatments"]');
    const panel = menu && menu.querySelector(':scope > .global-connected-panel-v402');
    const trigger = menu && menu.querySelector(':scope > .global-connected-item-v402');
    if (!nav || !menu || !panel || !trigger) return;
    let floating = null;
    let originalButtons = [];

    function isDetailPage(){
        return document.body.classList.contains('treatment-detail-open-v71') ||
            document.body.classList.contains('osteo-standalone-open-v260') ||
            document.querySelector('#treatmentDetailPageV71[aria-hidden="false"]') !== null;
    }
    function clearFloating(){
        if (floating) floating.remove();
        floating = null;
        if (document.body.classList.contains('v545-popup-open')) document.body.classList.remove('v545-popup-open');
    }
    function positionFloating(){
        if (!floating) return;
        const anchor = trigger.getBoundingClientRect();
        const navRect = nav.getBoundingClientRect();
        const width = Math.min(342,window.innerWidth-16);
        let left = anchor.left + anchor.width/2 - width/2;
        left = Math.min(Math.max(8,left),window.innerWidth-width-8);
        let top = Math.max(navRect.bottom,anchor.bottom) + 8;
        // Kaydırma sonrası menü açık kalırsa yine görünür bölgede olsun.
        top = Math.min(Math.max(8,top),Math.max(8,window.innerHeight-90));
        floating.style.setProperty('left',left+'px','important');
        floating.style.setProperty('top',top+'px','important');
        floating.style.setProperty('width',width+'px','important');
        floating.style.setProperty('max-height',Math.max(75,window.innerHeight-top-8)+'px','important');
    }
    function buildFloating(){
        clearFloating();
        originalButtons = Array.from(panel.querySelectorAll(':scope > button'));
        if (!originalButtons.length) return;
        floating = panel.cloneNode(true);
        floating.id = '';
        floating.removeAttribute('aria-hidden');
        floating.classList.remove('global-connected-panel-v402');
        floating.classList.add('v545-floating-panel');
        Array.from(floating.querySelectorAll('[id]')).forEach(el=>el.removeAttribute('id'));
        Array.from(floating.querySelectorAll(':scope > button')).forEach((button,index)=>{
            button.addEventListener('click',function(event){
                event.preventDefault();
                event.stopPropagation();
                const target = originalButtons[index];
                // Orijinal buton: bağlı rotalar, sayfa geçişi ve animasyonlar.
                clearFloating();
                menu.classList.remove('open');
                trigger.setAttribute('aria-expanded','false');
                panel.setAttribute('aria-hidden','true');
                if (target) target.click();
            });
        });
        document.documentElement.appendChild(floating);
        document.body.classList.add('v545-popup-open');
        positionFloating();
        // Bazı eski sayfa animasyonları menüyü ilk karelerde kaydırır.
        // İlk 0.4 sn boyunca gerçek konuma yeniden hizala.
        let frames = 0;
        function settle(){
            if (!floating || ++frames > 28) return;
            positionFloating();
            window.requestAnimationFrame(settle);
        }
        window.requestAnimationFrame(settle);
    }
    function sync(){
        const shouldOpen = menu.classList.contains('open') && isDetailPage() && !document.body.classList.contains('site-search-modal-open-v400');
        if (!shouldOpen){ clearFloating(); return; }
        if (!floating) buildFloating();
        else positionFloating();
    }
    new MutationObserver(sync).observe(menu,{attributes:true,attributeFilter:['class']});
    new MutationObserver(sync).observe(document.body,{attributes:true,attributeFilter:['class']});
    window.addEventListener('scroll',positionFloating,{passive:true,capture:true});
    window.addEventListener('resize',positionFloating,{passive:true});
    document.addEventListener('keydown',function(event){
        if (event.key === 'Escape') clearFloating();
    },true);
    document.addEventListener('pointerdown',function(event){
        if (!floating) return;
        if (!floating.contains(event.target) && !nav.contains(event.target)){
            clearFloating();
            menu.classList.remove('open');
            trigger.setAttribute('aria-expanded','false');
            panel.setAttribute('aria-hidden','true');
        }
    },true);
    sync();
})();



/* V561 | Sabit medya kategorileri + ana afis icinde dogrudan video oynatma. */
(function(){
  function initMediaV561(){
    const root=document.getElementById('mediaFixedV559');
    if(!root || root.dataset.readyV561==='1') return;
    root.dataset.readyV561='1';

    const tabs=Array.from(root.querySelectorAll('[data-media-filter-v559]'));
    const cards=Array.from(root.querySelectorAll('[data-media-tags-v559]'));
    const empty=root.querySelector('#mediaFixedEmptyV559');
    // V598: Filtre secilince liste basligini sabit ust menunun altina getir.
    // Filtreleme/icerik yapisi korunur; yalnizca gorunur kaydirma eklenir.
    const mediaListSection=root.querySelector('.media-fixed-list-section-v559');
    function scrollToFilteredMediaV598(){
      if(!mediaListSection || !document.body.classList.contains('media-page-open')) return;
      const topNavigation=document.getElementById('v548PremiumNav');
      const navigationBottom=topNavigation && getComputedStyle(topNavigation).display!=='none'
        ? Math.max(0, topNavigation.getBoundingClientRect().bottom) : 0;
      const topGap=Math.max(window.innerWidth<=760?76:96, navigationBottom+18);
      const destination=Math.max(0, window.scrollY + mediaListSection.getBoundingClientRect().top - topGap);
      const reduceMotion=window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      window.scrollTo({top:destination,behavior:reduceMotion?'auto':'smooth'});
    }
    tabs.forEach(tab=>tab.addEventListener('click',()=>{
      const key=tab.dataset.mediaFilterV559;
      tabs.forEach(btn=>{
        const selected=btn===tab;
        btn.classList.toggle('is-active',selected);
        btn.setAttribute('aria-pressed',String(selected));
      });
      let matches=0;
      cards.forEach(card=>{
        const visible=card.dataset.mediaOnlyV592 ? key===card.dataset.mediaOnlyV592 : (key==='all'||card.dataset.mediaTagsV559.split(/\s+/).includes(key));
        card.hidden=!visible;
        if(visible) matches++;
      });
      if(empty) empty.hidden=matches!==0;
      // DOM guncellendikten sonra yeni kategoriye ait kartlara kaydir.
      window.requestAnimationFrame(scrollToFilteredMediaV598);
    }));

    const mediaPage=document.getElementById('medyaPage');
    const feature=root.querySelector('.media-fixed-feature-v559');
    const player=document.getElementById('mediaInlinePlayerV561');
    const embed=document.getElementById('mediaInlineEmbedV561');
    const closeBtn=document.getElementById('mediaInlineCloseV561');
    const watchBtn=document.getElementById('mediaFixedHeroWatchV559');
    const playBtn=document.getElementById('mediaFixedHeroPlayV559');
    if(!feature||!player||!embed||!closeBtn||!watchBtn||!playBtn) return;
    // V587: Son gönderilen gerçek MP4 dosyası sitenin yerel HTML5 oynatıcısından açılır.
    // Youtube iframe, Referer veya üçüncü taraf izinleri gerekmez.
    // V588: Yeni MP4 videoları da aynı büyük HTML5 video alanında oynatılır.
    const nativeVideo=document.getElementById('mediaLocalVideoV585');
    if(!nativeVideo) return;
    nativeVideo.playsInline=true;
    const sourceEl=nativeVideo.querySelector('source');
    const featureTitle=feature.querySelector('.media-fixed-feature-copy-v559 h2');
    const featureDescription=feature.querySelector('.media-fixed-feature-copy-v559 p');
    const heroPhoto=feature.querySelector('.media-fixed-hero-photo-v559');
    const directYoutube=feature.querySelector('.media-fixed-direct-v584');
    const inlineYoutube=player.querySelector('.media-inline-youtube-v561');
    const videoCards=Array.from(root.querySelectorAll('[data-media-local-v588]'));
    let activeSource=sourceEl?.getAttribute('src')||'';
    let startAtSeconds=0;
    let seekHandler=null;

    // V647: Medyadan cikis veya video kapatma sonrasi devam noktasi saklanmaz.
    // Bir sonraki izleme tiklamasi daima ilk saniyeden baslar.
    function stopInlineVideo(){
      nativeVideo.pause();
      if(seekHandler){
        nativeVideo.removeEventListener('loadedmetadata',seekHandler);
        seekHandler=null;
      }
      startAtSeconds=0;
      try{nativeVideo.currentTime=0;}catch(_error){}
      player.hidden=true;
      feature.classList.remove('is-playing-v561');
    }

    function setSeekStart(offset){
      if(seekHandler){nativeVideo.removeEventListener('loadedmetadata',seekHandler);seekHandler=null;}
      startAtSeconds=offset;
      if(offset<=0) return;
      const seek=()=>{
        if(Number.isFinite(nativeVideo.duration)&&nativeVideo.duration>offset){
          try{nativeVideo.currentTime=offset;}catch(_error){}
        }
      };
      if(nativeVideo.readyState>=1) seek();
      else {
        seekHandler=()=>{seekHandler=null;seek();};
        nativeVideo.addEventListener('loadedmetadata',seekHandler,{once:true});
      }
    }

    function playInlineVideo(){
      if(player.hidden){
        player.hidden=false;
        feature.classList.add('is-playing-v561');
      }
      const attempt=nativeVideo.play();
      if(attempt?.catch) attempt.catch(()=>{});
    }

    function selectMediaCard(card){
      const src=card.getAttribute('data-media-local-v588');
      if(!src || !sourceEl) return;
      const title=card.getAttribute('data-media-title-v588')||'Video';
      const desc=card.getAttribute('data-media-description-v588')||'';
      const poster=card.getAttribute('data-media-poster-v588')||'';
      const youtube=card.getAttribute('data-media-youtube-v588')||'';
      const offset=Math.max(0,Number(card.getAttribute('data-media-start-v588'))||0);
      const isDifferent=activeSource!==src;
      nativeVideo.pause();
      if(featureTitle) featureTitle.textContent=title;
      if(featureDescription) featureDescription.textContent=desc;
      if(heroPhoto && poster) heroPhoto.src=poster;
      if(poster) nativeVideo.poster=poster;
      for(const link of [directYoutube,inlineYoutube]){
        if(!link)continue;
        link.hidden=!youtube;
        if(youtube)link.href=youtube;
      }
      playBtn.setAttribute('aria-label',title+' videosunu bu alanda oynat');
      player.setAttribute('aria-label',title+' video oynatıcı');
      nativeVideo.setAttribute('aria-label',title+' videosu');
      videoCards.forEach(other=>{
        const selected=other===card;
        other.classList.toggle('is-selected-v588',selected);
        other.setAttribute('aria-pressed',String(selected));
      });
      if(isDifferent){
        activeSource=src;
        sourceEl.setAttribute('src',src);
        nativeVideo.load();
      }else{
        try{nativeVideo.currentTime=0;}catch(_error){}
      }
      setSeekStart(offset);
      // Sadece kullanıcı kart seçtiğinde oynat; tümü yerel MP4, YouTube iframe yok.
      playInlineVideo();
    }

    // V647: Varsayilan tanitim videosu dahil butun videolar 0:00'dan baslar.
    setSeekStart(0);
    watchBtn.addEventListener('click',playInlineVideo);
    playBtn.addEventListener('click',playInlineVideo);
    videoCards.forEach(card=>card.addEventListener('click',()=>{
      selectMediaCard(card);
      feature.scrollIntoView({behavior:'smooth',block:'center'});
    }));
    closeBtn.addEventListener('click',()=>{stopInlineVideo();playBtn.focus({preventScroll:true});});
    document.addEventListener('keydown',event=>{
      if(event.key==='Escape'&&!player.hidden){stopInlineVideo();playBtn.focus({preventScroll:true});}
    });

    // V641: Menü geçişleri her zaman #medyaPage aria-hidden değerini değiştirmiyor.
    // Hem sayfanın kendi görünürlüğünü hem body sayfa sınıfını izle.
    // Böylece menüler, arama, alt sayfalar ve tarayıcı geri/ileri işlemleri
    // sırasında video başka bir sekmede ses çalmaya devam etmez.
    if(mediaPage){
      const isMediaPageVisibleV641=()=>
        document.body.classList.contains('media-page-open') &&
        mediaPage.getAttribute('aria-hidden')!=='true' &&
        !document.hidden;

      const stopMediaWhenHiddenV641=()=>{
        if(isMediaPageVisibleV641()) return;
        // Görünür oynatıcı kapanmış olsa bile bütün medya öğelerini durdur.
        // Menü geçişi video sesini kesinlikle arkada bırakmasın.
        mediaPage.querySelectorAll('video,audio').forEach(element=>{
          if(typeof element.pause==='function') element.pause();
        });
        // Sekme degisiminde kapak gorunur, ilerleme cubugu sifirlanir.
        // Gizli hale gelmis olsa bile onceki izleme konumu saklanmaz.
        stopInlineVideo();
      };

      const observerV641=new MutationObserver(stopMediaWhenHiddenV641);
      observerV641.observe(mediaPage,{
        attributes:true,
        attributeFilter:['aria-hidden','hidden','class']
      });
      observerV641.observe(document.body,{
        attributes:true,
        attributeFilter:['class']
      });
      document.addEventListener('visibilitychange',stopMediaWhenHiddenV641);
      window.addEventListener('pagehide',stopMediaWhenHiddenV641);
      window.addEventListener('popstate',()=>queueMicrotask(stopMediaWhenHiddenV641));
      window.addEventListener('hashchange',()=>queueMicrotask(stopMediaWhenHiddenV641));
      stopMediaWhenHiddenV641();
    }
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',initMediaV561,{once:true});
  else initMediaV561();
})();


// =========================================================
// V568 — YEDİ DAMAR YOLU KARTININ TAMAMI DETAY AÇSIN
// Mevcut "Bilgi Edin" düğmelerinin işlevini aynen kullanır.
// Böylece serum detayları, Geri işlevi ve V556/V565 yönlendirmeleri korunur.
// =========================================================
(function initSerumWholeCardV568(){
    function bind(){
        const vascularView = document.querySelector('[data-treatment-detail-view="damar-yolu"]');
        if (!vascularView) return;
        const cards = Array.from(vascularView.querySelectorAll('.serum-grid-modern-v307 > .serum-card-modern-v307'));
        cards.forEach((card) => {
            if (card.dataset.serumCardBoundV568 === 'true') return;
            const openButton = card.querySelector('.serum-detail-open-v235');
            if (!openButton) return;
            card.dataset.serumCardBoundV568 = 'true';
            card.tabIndex = 0;
            const heading = card.querySelector('h2')?.textContent?.trim() || 'Serum';
            card.setAttribute('aria-label', heading + ' bilgi sayfasını aç');
            // İçeride zaten tıklanabilir bir düğmeye/linke basıldıysa bir kez daha tetikleme.
            function activateFromCard(event){
                if (!(event.target instanceof Element)) return;
                if (event.target.closest('button, a, input, select, textarea, summary, [role="button"], [role="link"]')) return;
                if (!openButton.disabled) openButton.click();
            }
            card.addEventListener('click', activateFromCard);
            card.addEventListener('keydown', (event) => {
                if (event.target !== card) return;
                if (event.key !== 'Enter' && event.key !== ' ') return;
                event.preventDefault();
                if (!openButton.disabled) openButton.click();
            });
        });
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bind, {once:true});
    else bind();
})();


// V668: Ana sayfa videosu kaldırıldı; sabit görsel için video oynatma denetimi yok.


/* V571 - Gerçek klinik galerisi: yalnızca resme tıklanınca büyük göster. */
(function(){
 function ready(){
  var root=document.getElementById('aboutPanelInstitutionV125');
  if(!root||!root.querySelector('.institution-gallery-v571'))return;
  var dialog=document.createElement('dialog');
  dialog.className='institution-photo-dialog-v571';
  dialog.setAttribute('aria-label','Klinik fotoğrafı');
  dialog.innerHTML='<button type="button" class="institution-dialog-close-v571" aria-label="Fotoğrafı kapat">×</button><img alt=""><div class="institution-dialog-caption-v571"></div>';
  document.body.appendChild(dialog);
  var image=dialog.querySelector('img'),caption=dialog.querySelector('.institution-dialog-caption-v571');
  root.addEventListener('click',function(event){
    var card=event.target.closest('.institution-photo-card-v571');
    if(!card||!root.contains(card))return;
    var imageName=card.getAttribute('data-clinic-photo-v571');
    if(!/^[a-z0-9-]+\.webp$/.test(imageName||''))return;
    var label=card.getAttribute('data-clinic-title-v571')||'Klinik fotoğrafı';
    image.src='./'+imageName;
    image.alt=label;
    caption.textContent=label;
    if(typeof dialog.showModal==='function')dialog.showModal();
  });
  dialog.querySelector('.institution-dialog-close-v571').addEventListener('click',function(){dialog.close();});
  dialog.addEventListener('click',function(event){if(event.target===dialog)dialog.close();});
 }
 if(document.getElementById('v548PremiumNav'))ready();
 else if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready,{once:true});
 else ready();
})();




/* V578 — Tedavi Alanları özel hastalık sayfalarında görünür Ana Sayfa düğmesi.
   V402/V548 ortak yönlendirmesini kullanır; detayları ve animasyonları korur. */
(function () {
  'use strict';
  const screens = ['asSpecialViewV274', 'treatmentSpecialViewV279'];
  function goHomeFromDiseaseV578(event) {
    event.preventDefault();
    event.stopPropagation();
    // Premium üst menü merkezi yönlendirme, katman temizleme ve geçiş animasyonunu yönetir.
    const brand = document.querySelector('#v548PremiumNav [data-v548-route="home"]');
    if (brand) { brand.click(); return; }
    const legacyBrand = document.getElementById('globalConnectedBrandV402');
    if (legacyBrand) { legacyBrand.click(); return; }
    const home = document.getElementById('anasayfa');
    home?.scrollIntoView({behavior:'smooth', block:'start'});
  }
  function addHomeButtonsV578() {
    screens.forEach(id => {
      const view = document.getElementById(id);
      if (!view) return;
      const controls = view.querySelector('.special-head-controls-v448');
      if (!controls || controls.querySelector('.special-home-v578')) return;
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'special-home-v578';
      button.setAttribute('aria-label', 'Ana sayfaya dön');
      button.setAttribute('title', 'Ana sayfaya dön');
      button.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/></svg><span class="special-home-desktop-v578">Ana Sayfaya Dön</span><span class="special-home-mobile-v578">Ana Sayfa</span>';
      button.addEventListener('click', goHomeFromDiseaseV578);
      controls.insertBefore(button, controls.firstChild);
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', addHomeButtonsV578, {once:true});
  } else {
    addHomeButtonsV578();
  }
})();

// V589 - Osteopati manuel video: yalnızca görünürken yüklenir/oynar.
// Görüntü ve oynatma davranışı korunur; gizliyken veri ve CPU harcamaz.
(function(){
  const panel=document.getElementById('osteoChiroV105');
  const video=panel?.querySelector('.osteo-chiro-video-v108 video');
  const special=document.getElementById('osteoSpecialViewV259');
  const osteo=document.querySelector('[data-treatment-detail-view="osteopati"]');
  if(!video||!special||!osteo)return;
  let lastVisible=false;
  function sync(){
    const shell=document.getElementById('treatmentDetailPageV71');
    const visible=!document.hidden &&
      document.body.classList.contains('treatment-detail-open-v71') &&
      shell?.getAttribute('aria-hidden')!=='true' &&
      osteo.classList.contains('active') &&
      !special.hidden && special.getAttribute('aria-hidden')!=='true' &&
      panel.classList.contains('is-active-v258');
    if(!visible){
      if(!video.paused)video.pause();
      lastVisible=false;
      return;
    }
    if(!lastVisible||video.paused){
      video.muted=true;
      const p=video.play();
      if(p?.catch)p.catch(()=>{});
    }
    lastVisible=true;
  }
  const observer=new MutationObserver(sync);
  for(const [el,attrs] of [[document.body,['class']],[document.getElementById('treatmentDetailPageV71'),['aria-hidden']],[osteo,['class']],[special,['hidden','aria-hidden']],[panel,['class']]]){
    if(el)observer.observe(el,{attributes:true,attributeFilter:attrs});
  }
  document.addEventListener('visibilitychange',sync);
  video.addEventListener('pause',()=>{if(lastVisible&&!document.hidden)setTimeout(sync,140);});
  sync();
})();


// =========================================================
// V601 - BESLENME: 48 tarifte malzemeye göre arama ve kompakt kartlar
// V175 kategori yönlendirmesi / V385 tarif verileri olduğu gibi korunur.
// =========================================================
(function () {
  'use strict';
  function initNutritionV601() {
    const view = document.querySelector('[data-health-detail-view="beslenme"]');
    const toggle = document.getElementById('nutritionSearchToggleV601');
    const panel = document.getElementById('nutritionSearchPanelV601');
    const input = document.getElementById('nutritionSearchInputV601');
    const results = document.getElementById('nutritionSearchResultsV601');
    const status = document.getElementById('nutritionSearchStatusV601');
    const clear = document.getElementById('nutritionSearchClearV601');
    if (!view || !toggle || !panel || !input || !results || !status || view.dataset.nutritionV601Ready) return;
    view.dataset.nutritionV601Ready = 'true';

    const categories = Array.from(view.querySelectorAll('.nutrition-card-v174 [data-nutrition-open]'));
    const titles = new Map(categories.map(button => [button.dataset.nutritionOpen,
      button.closest('.nutrition-card-v174')?.querySelector('h3')?.textContent?.trim() || 'Beslenme']));
    const normalize = value => String(value || '').toLocaleLowerCase('tr-TR')
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .replace(/ı/g,'i').replace(/ğ/g,'g').replace(/ş/g,'s')
      .replace(/ü/g,'u').replace(/ö/g,'o').replace(/ç/g,'c')
      .replace(/\s+/g,' ').trim();
    const allRecipes = [];
    const dialog = document.createElement('dialog');
    dialog.className = 'nutrition-recipe-dialog-v601';
    dialog.setAttribute('aria-label','Besin değerleri hakkında ayrıntılı bilgi');
    // V602: Browser reset CSS dialogun margin:auto varsayılanını kaldırıyordu.
    // Bağımsız yapışkan üst bar + yalnız içeride kayan, ortalanmış modal.
    dialog.innerHTML = `
      <div class="nutrition-recipe-frame-v602">
        <div class="nutrition-recipe-toolbar-v602">
          <span class="nutrition-recipe-toolbar-identity-v602">
            <span class="nutrition-recipe-toolbar-icon-v602" aria-hidden="true">✦</span>
            <span><strong>BESLENME REHBERİ</strong><small>Gıdaların özellikleri ve yararları</small></span>
          </span>
          <button type="button" class="nutrition-recipe-dialog-close-v601" aria-label="Bilgi penceresini kapat" title="Kapat">×</button>
        </div>
        <div class="nutrition-recipe-scroll-v602" tabindex="-1"><div class="nutrition-recipe-dialog-inner-v601"></div></div>
      </div>`;
    document.body.appendChild(dialog);
    const dialogInner = dialog.querySelector('.nutrition-recipe-dialog-inner-v601');
    const dialogClose = dialog.querySelector('.nutrition-recipe-dialog-close-v601');
    dialogClose.addEventListener('click', () => dialog.close());
    dialog.addEventListener('click', event => {if (event.target === dialog) dialog.close();});


    // V661: Eski sekme kartlarına değil, açılan 48 gıda bilgi penceresine özel notlar.
    function createFoodJourneyV661(recipe) {
      const raw = normalize(recipe.ingredients.join(' '));
      const find = entries => entries.find(entry => entry[0].some(x => raw.includes(normalize(x))))?.[1] || '';
      const starch = find([
        [['yulaf'],'yulaf'],[['bulgur'],'bulgur'],[['patates'],'patates'],[['ekmek','tost','lavaş'],'tam tahıllar'],
        [['mercimek'],'mercimek'],[['nohut'],'nohut'],[['fasulye'],'fasulye'],[['pirinç'],'pirinç'],
        [['karabuğday'],'karabuğday'],[['un'],'un veya tahıl ürünleri']
      ]);
      const protein = find([
        [['somon'],'somon'],[['balık','fileto'],'balık'],[['tavuk'],'tavuk'],[['kıyma','köfte'],'et'],
        [['yumurta'],'yumurta'],[['mercimek'],'mercimek'],[['nohut'],'nohut'],[['fasulye'],'fasulye'],
        [['yoğurt'],'yoğurt'],[['kefir'],'kefir'],[['peynir'],'peynir'],[['süt'],'süt'],[['tahin'],'tahin'],
        [['badem'],'badem'],[['ceviz'],'ceviz'],[['yulaf'],'yulaf']
      ]);
      const fat = find([
        [['zeytinyağı','zeytin yağı'],'zeytinyağı'],[['ceviz'],'ceviz'],[['badem'],'badem'],[['avokado'],'avokado'],
        [['tahin'],'tahin'],[['zeytin'],'zeytin'],[['somon'],'somon'],[['balık'],'balık']
      ]);
      const fiber = find([
        [['mercimek'],'mercimek'],[['nohut'],'nohut'],[['fasulye'],'fasulye'],[['yulaf'],'yulaf'],
        [['bulgur'],'bulgur'],[['brokoli'],'brokoli'],[['ıspanak'],'ıspanak'],[['kabak'],'kabak'],
        [['havuç'],'havuç'],[['elma'],'elma'],[['pancar'],'pancar'],[['enginar'],'enginar'],
        [['meyve'],'meyve'],[['yeşillik','roka','maydanoz'],'yeşillikler'],[['sebze','domates','salatalık'],'sebzeler']
      ]);
      const fermented = raw.includes(normalize('yoğurt')) ? 'yoğurt' : raw.includes(normalize('kefir')) ? 'kefir' : '';
      let enzyme = 'Sindirim sırasında amilaz nişastayı, proteazlar proteinleri, lipaz ise yağları parçalamaya yardımcı olur.';
      if (starch) enzyme += ' Bu öğünde nişasta içeren ' + starch + ' gibi besinlerin sindiriminde amilaz rol alır.';
      else if (protein) enzyme += ' Bu öğünde özellikle ' + protein + ' proteinlerinin sindirimi önemlidir.';
      if (fat) enzyme += ' ' + fat.charAt(0).toLocaleUpperCase('tr-TR') + fat.slice(1) + ' içindeki yağların sindiriminde de lipaz görev alır.';
      const amino = protein
        ? protein.charAt(0).toLocaleUpperCase('tr-TR') + protein.slice(1) + ' proteinleri sindirildiğinde amino asitler açığa çıkar. Amino asitler kasların, bağ dokusunun ve enzimlerin normal yapımında kullanılır.'
        : 'Bu besin seçeneğinin protein miktarı sınırlı olabilir. Günün diğer öğünlerinde kişiye uygun protein kaynakları almak, temel amino asit gereksinimini karşılamaya yardımcı olur.';
      let bowel = fiber
        ? fiber.charAt(0).toLocaleUpperCase('tr-TR') + fiber.slice(1) + ' içindeki lif, bağırsak hareketleri ve mikrobiyota çeşitliliğine katkı sağlayabilir.'
        : 'Dengeli bağırsak işlevi için günün diğer öğünlerinde farklı lif kaynakları ve yeterli sıvı önemlidir.';
      if (fermented) bowel += ' ' + fermented.charAt(0).toLocaleUpperCase('tr-TR') + fermented.slice(1) + ' fermente süt ürünüdür; canlı kültür miktarı ürüne göre değişir.';
      bowel += ' Şişkinlik veya gıda intoleransında kişisel tolerans dikkate alınmalıdır.';
      const chronicBySection = {
        balanced: 'Diyabet, böbrek hastalığı veya düzenli ilaç kullanımında porsiyon ve besin seçimi kişiye göre değişir. Tek bir öğün hastalıkları tedavi etmez.',
        pregnancy: 'Gebelikte gıda güvenliği, yeterli folat ve protein alımı önemlidir. Takviye gereksinimi ve özel hastalıklar hekimle değerlendirilmelidir.',
        children: 'Çocuklarda yaşa uygun porsiyon, alerjiler ve boğulma riski dikkate alınmalıdır. Büyüme veya sindirim sorununda çocuk hekimine başvurulmalıdır.',
        autoimmune: 'Romatoid artrit, ankilozan spondilit ve psöriyatik artritte beslenme ilaçların yerine geçmez. Bağırsak yakınmaları ve kişisel tolerans önemlidir.',
        digestion: 'İrritabl bağırsak, çölyak veya iltihabi bağırsak hastalıklarında aynı lif ve süt ürünleri herkese uygun değildir; bireysel değerlendirme gerekir.',
        heart: 'Tansiyon, kolesterol ve kalp-damar hastalıklarında tuz, yağ türü ve porsiyonlar kullanılan ilaçlarla birlikte değerlendirilmelidir.',
        weight: 'Kilo kontrolünde tek bir gıda hızlı sonuç sağlamaz. Enerji dengesi, hareket, uyku ve kronik hastalıklara uygun porsiyonlar birlikte önemlidir.',
        detox: 'Karaciğer hastalığında beslenme kişiselleştirilmelidir; hiçbir besin tek başına karaciğeri temizlemez veya ilaçların yerini tutmaz.'
      };
      const journey = document.createElement('section');
      journey.className = 'nutrition-v661-journey';
      const heading = document.createElement('strong');
      heading.className = 'nutrition-v661-journey-title';
      heading.textContent = 'Bu gıdalar vücudumuzda nasıl değerlendirilir?';
      journey.appendChild(heading);
      const grid = document.createElement('div');
      grid.className = 'nutrition-v661-journey-grid';
      [
        ['Sindirim enzimleri', enzyme],
        ['Amino asitler ve dokular', amino],
        ['Bağırsak sağlığı', bowel],
        ['Kronik hastalıklarda beslenme', chronicBySection[recipe.key] || chronicBySection.balanced]
      ].forEach(([title, description]) => {
        const article=document.createElement('article');
        const h3=document.createElement('h3'); h3.textContent=title;
        const p=document.createElement('p'); p.textContent=description;
        article.append(h3,p); grid.appendChild(article);
      });
      journey.appendChild(grid);
      return journey;
    }

    function openRecipe(recipe) {
      if (!recipe || !recipe.card) return;
      if (dialog.open) dialog.close();
      dialogInner.replaceChildren();
      const media = document.createElement('div'); media.className = 'nutrition-recipe-modal-media-v601';
      const img = recipe.card.querySelector('.pregnancy-recipe-media-v384 img');
      if (img) {
        const photo=img.cloneNode(true);
        photo.addEventListener('error',()=>{media.hidden=true;},{once:true});
        media.appendChild(photo);
        if (photo.complete && !photo.naturalWidth) media.hidden=true;
      } else media.hidden=true;
      const body = document.createElement('div'); body.className = 'nutrition-recipe-modal-body-v601';
      const category = document.createElement('span');category.className='nutrition-recipe-modal-category-v601';
      category.textContent=recipe.category+' • '+recipe.kicker;
      const heading = document.createElement('h2');heading.id='nutritionRecipeModalHeadingV601';heading.textContent=recipe.title;
      const columns = document.createElement('div');columns.className='nutrition-recipe-modal-sections-v601';
      recipe.card.querySelectorAll('.pregnancy-recipe-columns-v384 section').forEach(section => columns.appendChild(section.cloneNode(true)));
      const why = recipe.card.querySelector('.pregnancy-recipe-why-v384');
      const whyClone = why ? why.cloneNode(true) : document.createElement('div');
      whyClone.className='nutrition-recipe-modal-why-v601';
      const note = document.createElement('p');note.className='nutrition-recipe-modal-note-v601';
      note.textContent='Genel bilgilendirme amaçlıdır; kişisel beslenme planı için hekim ve diyetisyene danışın.';
      // Açıklamalar kartlarda değil, yalnızca "Gıdaların Faydaları" penceresinde görünür.
      const foodJourney = createFoodJourneyV661(recipe);
      body.append(category,heading,columns,whyClone,foodJourney,note);
      dialogInner.append(media,body);
      dialog.setAttribute('aria-labelledby',heading.id);
      if (typeof dialog.showModal==='function') dialog.showModal(); else dialog.setAttribute('open','');
      const modalScroller = dialog.querySelector('.nutrition-recipe-scroll-v602');
      if (modalScroller) modalScroller.scrollTop = 0;
      dialogClose.focus({preventScroll:true});
    }

    view.querySelectorAll('[data-nutrition-detail]').forEach(detail => {
      const key = detail.getAttribute('data-nutrition-detail');
      const category = titles.get(key) || 'Beslenme';
      detail.querySelectorAll('.pregnancy-recipe-v384').forEach((card, index) => {
        const title = card.querySelector('.pregnancy-recipe-content-v384 > h2')?.textContent?.trim() || '';
        const kicker = card.querySelector('.pregnancy-recipe-kicker-v384')?.textContent?.trim() || 'BESİN BİLGİSİ';
        const ingredients = (card.getAttribute('data-nutrition-ingredients-v656') || '').split('|').filter(Boolean);
        const reason = card.querySelector('.pregnancy-recipe-why-v384 > p')?.textContent?.trim() || '';
        if (!title || !ingredients.length) return;
        const recipe = {key, category, title, kicker, ingredients, card,
          searchText:normalize([title, ingredients.join(' '), category].join(' ')),
          image:card.querySelector('.pregnancy-recipe-media-v384 img')?.getAttribute('src') || ''};
        allRecipes.push(recipe);
        card.dataset.nutritionRecipeV601 = key+'-'+String(index+1).padStart(2,'0');
        const content = card.querySelector('.pregnancy-recipe-content-v384');
        if (content && !content.querySelector('.nutrition-recipe-preview-v601')) {
          const preview = document.createElement('div');preview.className='nutrition-recipe-preview-v601';
          const whyShort = document.createElement('p');
          whyShort.textContent = reason;
          const tag = document.createElement('small');
          tag.textContent='Öne çıkan gıdalar: '+Array.from(card.querySelectorAll('.pregnancy-recipe-columns-v384 section:first-child li')).slice(0,3).map(li=>li.textContent.split(':')[0].trim()).join(' · ');
          const button = document.createElement('button');button.type='button';
          button.className='nutrition-recipe-open-v601';
          button.innerHTML='<span>Gıdaların Faydaları</span><span aria-hidden="true">→</span>';
          button.setAttribute('aria-label',title+' içindeki gıdaların faydalarını aç');
          button.addEventListener('click',() => openRecipe(recipe));
          preview.append(whyShort,tag,button);
          content.appendChild(preview);
        }
      });
    });
    view.querySelector('.nutrition-search-quantity-v601').textContent = allRecipes.length+' İçerik';

    function setSearchOpen(open) {
      panel.hidden=!open;
      toggle.setAttribute('aria-expanded',String(open));
      if (open) window.requestAnimationFrame(() => input.focus({preventScroll:true}));
    }
    function addResult(recipe) {
      const button=document.createElement('button');button.type='button';button.className='nutrition-search-result-v601';
      const image=document.createElement('img');image.src=recipe.image;image.alt='';image.loading='lazy';
      const copy=document.createElement('span');copy.className='nutrition-search-result-copy-v601';
      const category=document.createElement('small');category.textContent=recipe.category;
      const name=document.createElement('strong');name.textContent=recipe.title;
      const ingredients=document.createElement('em');ingredients.textContent='Öne çıkan gıdalar: '+Array.from(recipe.card.querySelectorAll('.pregnancy-recipe-columns-v384 section:first-child li')).slice(0,2).map(li=>li.textContent.split(':')[0].trim()).join(' · ');
      copy.append(category,name,ingredients);
      const arrow=document.createElement('span');arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');
      button.append(image,copy,arrow);
      button.setAttribute('aria-label',recipe.title+' — '+recipe.category+' içinde besin bilgilerini görüntüle');
      button.addEventListener('click',() => {
        setSearchOpen(false);
        const opener=view.querySelector('[data-nutrition-open="'+recipe.key+'"]');
        if (opener) opener.click();
        window.requestAnimationFrame(()=>openRecipe(recipe));
      });
      return button;
    }
    function render() {
      const query=normalize(input.value);
      results.replaceChildren();
      if (!query) {
        status.textContent='Bir gıda adı yazarak '+allRecipes.length+' besin içeriğinde arama yapabilirsiniz.';
        return;
      }
      const matching=allRecipes.filter(recipe=>recipe.searchText.includes(query));
      status.textContent=matching.length
        ? allRecipes.length+' besin içeriğinde '+matching.length+' sonuç bulundu.'
        : 'Bu aramayla eşleşen içerik bulunamadı. Başka bir besin adı deneyin.';
      const fragment=document.createDocumentFragment();
      matching.forEach(recipe=>fragment.appendChild(addResult(recipe)));
      results.appendChild(fragment);
    }
    toggle.addEventListener('click',()=>{setSearchOpen(panel.hidden); if (!panel.hidden) render();});
    input.addEventListener('input',render);
    clear.addEventListener('click',()=>{input.value='';render();input.focus({preventScroll:true});});
    const inputLine = view.querySelector('.nutrition-search-inputline-v601');
    if (inputLine) inputLine.addEventListener('click',event=>{
      if (event.target===inputLine) input.focus({preventScroll:true});
    });
    view.querySelectorAll('[data-nutrition-query-v601]').forEach(button=>button.addEventListener('click',()=>{
      input.value=button.dataset.nutritionQueryV601;
      setSearchOpen(true);render();
      input.focus({preventScroll:true});
    }));
    view.querySelectorAll('[data-nutrition-open]').forEach(button=>button.addEventListener('click',()=>setSearchOpen(false)));
    document.addEventListener('keydown',event=>{if(event.key==='Escape' && !panel.hidden){setSearchOpen(false);toggle.focus();}});
    // Diğer bölümlerden mevcut site genel araması ve geri dönüş etkilenmez.
    window.nutritionSearchV601={count:allRecipes.length, search:q=>allRecipes.filter(r=>r.searchText.includes(normalize(q))).map(r=>({title:r.title,category:r.category}))};
    render();
  }
  if (document.readyState==='loading') document.addEventListener('DOMContentLoaded',initNutritionV601,{once:true});
  else initNutritionV601();
})();


/* V603 - Supplementler: live arama, filtre ve bağımsız, ortalanmış detay penceresi. */
(function(){
  'use strict';
  function init(){
    const view=document.getElementById('sup603Explorer')?.closest('[data-health-detail-view="supplementler"]');
    if(!view||view.dataset.sup603Ready)return;
    view.dataset.sup603Ready='true';
    const cards=Array.from(view.querySelectorAll('[data-sup603-card]'));
    const searchToggle=view.querySelector('#sup603SearchToggle');
    const searchPanel=view.querySelector('#sup603SearchPanel');
    const input=view.querySelector('#sup603Input');
    const status=view.querySelector('#sup603Status');
    const empty=view.querySelector('#sup603Empty');
    const buttons=Array.from(view.querySelectorAll('[data-sup603-filter]'));
    const dialog=document.getElementById('sup603Dialog');
    const dialogContent=document.getElementById('sup603DialogContent');
    const dialogScroller=document.getElementById('sup603DialogScroll');
    const dialogClose=document.getElementById('sup603Close');
    if(!cards.length||!dialog||!input)return;
    // Top-layer modal: move outside section clipping / hidden page transitions.
    if(dialog.parentElement!==document.body)document.body.appendChild(dialog);
    const normalize=s=>String(s||'').toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/ğ/g,'g').replace(/ş/g,'s').replace(/ü/g,'u').replace(/ö/g,'o').replace(/ç/g,'c').replace(/[‑–—-]/g,'').replace(/\s+/g,' ').trim();
    let currentCategory='all';
    const corpus=cards.map(card=>({card,text:normalize(card.dataset.sup603Search)}));
    function render(){
      const q=normalize(input.value);
      let count=0;
      corpus.forEach(({card,text})=>{
        const matchCategory=currentCategory==='all'||card.dataset.sup603Category===currentCategory;
        const matchText=!q||text.includes(q);
        card.hidden=!(matchCategory&&matchText);
        if(!card.hidden)count++;
      });
      empty.hidden=!!count;
      status.textContent=count+' / '+cards.length+' içerik gösteriliyor'+(q||currentCategory!=='all'?'. Filtreler aktif.':'.');
    }
    function setSearchOpen(open){
      searchPanel.hidden=!open;searchToggle.setAttribute('aria-expanded',String(open));
      if(open)input.focus({preventScroll:true});
    }
    function setCategory(name){
      currentCategory=name;
      buttons.forEach(button=>{const active=button.dataset.sup603Filter===name;button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active));});
      render();
    }
    searchToggle.addEventListener('click',()=>setSearchOpen(searchPanel.hidden));
    view.querySelector('#sup603Clear').addEventListener('click',()=>{input.value='';render();input.focus({preventScroll:true});});
    input.addEventListener('input',render);
    input.addEventListener('keydown',event=>{if(event.key==='Escape'&&input.value){event.stopPropagation();input.value='';render();}});
    view.querySelectorAll('[data-sup603-query]').forEach(button=>button.addEventListener('click',()=>{input.value=button.dataset.sup603Query;setSearchOpen(true);render();}));
    buttons.forEach(button=>button.addEventListener('click',()=>setCategory(button.dataset.sup603Filter)));
    view.querySelector('#sup603Reset').addEventListener('click',()=>{input.value='';setCategory('all');setSearchOpen(false);});
    const missingImage=(img)=>{if(img&&!img.naturalWidth)img.classList.add('sup603-img-missing');};
    cards.forEach(card=>{const img=card.querySelector('img');if(img){img.addEventListener('error',()=>missingImage(img));if(img.complete)missingImage(img);}});
    let lastTrigger=null;
    function close(){if(dialog.open)dialog.close();}
    function open(slug,trigger){
      // Selection limited to the six in-page templates, never evaluated as HTML input.
      if(!/^[a-z0-9]+$/.test(slug))return;
      const template=document.getElementById('sup603-template-'+slug);
      if(!template)return;
      if(dialog.open)close();
      lastTrigger=trigger;
      dialogContent.replaceChildren(template.content.cloneNode(true));
      const image=dialogContent.querySelector('.sup603-detail-photo img');
      if(image){image.addEventListener('error',()=>missingImage(image));if(image.complete)missingImage(image);}
      if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');
      if(dialogScroller)dialogScroller.scrollTop=0;
      dialogClose.focus({preventScroll:true});
    }
    view.addEventListener('click',event=>{const btn=event.target.closest('[data-sup603-open]');if(btn&&view.contains(btn))open(btn.dataset.sup603Open,btn);});
    dialogClose.addEventListener('click',close);
    dialog.addEventListener('click',event=>{if(event.target===dialog)close();});
    dialog.addEventListener('close',()=>{if(lastTrigger&&lastTrigger.isConnected)lastTrigger.focus({preventScroll:true});});
    // Leaving supplement section should close modal and reset focus state.
    const healthView=view;
    new MutationObserver(()=>{if(dialog.open&&(!healthView.classList.contains('active')&&healthView.getAttribute('aria-hidden')==='true'))close();})
      .observe(healthView,{attributes:true,attributeFilter:['class','aria-hidden']});
    window.supplementSearchV603={count:cards.length,search:q=>corpus.filter(e=>e.text.includes(normalize(q))).map(e=>e.card.querySelector('h2')?.textContent?.trim())};
    render();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();


// V616 - Defer small animated header portrait until after first meaningful paint.
// The static, unchanged doctor image always remains as the fallback.
(function(){
    'use strict';
    const video=document.querySelector('.v594-avatar-motion-v594');
    const source=video?.querySelector('source[data-v616-src]');
    if(!video||!source)return;
    const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
    const saveData=Boolean(navigator.connection?.saveData);
    if(reduced.matches||saveData)return;
    let started=false;
    function activate(){
        if(started||document.hidden)return;
        started=true;
        source.src=source.dataset.v616Src;
        video.preload='metadata';
        video.load();
        const promise=video.play();
        if(promise?.catch)promise.catch(()=>{});
    }
    function schedule(){
        if('requestIdleCallback' in window)window.requestIdleCallback(activate,{timeout:1300});
        else window.setTimeout(activate,700);
    }
    if(document.readyState==='complete')schedule();
    else window.addEventListener('load',schedule,{once:true});
    window.setTimeout(activate,3400);
    document.addEventListener('visibilitychange',()=>{
        if(document.hidden){if(!video.paused)video.pause();}
        else if(!started)activate();
        else if(video.paused){const promise=video.play();if(promise?.catch)promise.catch(()=>{});}
    });
})();


